function Navbar() {
  const navigate = useNavigate();

  const userName = localStorage.getItem("user_name");
  const role = localStorage.getItem("role");

  const handleLogout = () => {
    localStorage.clear();
    navigate("/");
  };

  return (
    <nav style={{
      display: "flex",
      justifyContent: "space-between",
      padding: "18px 40px",
      background: "#fff",
      boxShadow: "0 4px 12px rgba(0,0,0,0.08)"
    }}>

      <h2 style={{ color: "#4a148c" }}>LMS Platform</h2>

      <div style={{ display: "flex", gap: "20px", alignItems: "center" }}>

        {/* ❌ Login/Signup hide after login */}
        {!userName && (
          <>
            <Link to="/">Login</Link>
            <Link to="/signup">Signup</Link>
          </>
        )}

        {/* ✅ Show after login */}
        {userName && (
          <>
            <Link to="/courses">Courses</Link>

            {role === "teacher" && <Link to="/teacher-dashboard">Teacher Panel</Link>}
            {role === "student" && <Link to="/student-dashboard">Student Panel</Link>}

            <span style={{ color: "#7b1fa2", fontWeight: "bold" }}>
              Hi, {userName}
            </span>

            <button
              onClick={handleLogout}
              style={{
                background: "#7b1fa2",
                color: "#fff",
                border: "none",
                padding: "8px 14px",
                borderRadius: "8px",
                cursor: "pointer"
              }}
            >
              Logout
            </button>
          </>
        )}
      </div>
    </nav>
  );
}
